FAMILIES = []
def family(name, split, rows):
    assert len(rows) == 20, (name, len(rows))
    FAMILIES.append((name, split, rows))
def r(left, right, scenario, amounts, refs=(None, None), docs=(None, None), extra=None, category='procurement-context'):
    return dict(left=left, right=right, scenario=scenario, amounts=amounts, refs=refs, docs=docs, extra=extra or ({}, {}), category=category)

