def make_dataset():
    rng = random.Random(20261014)
    cases = []
    epoch = datetime(2026, 9, 1, tzinfo=timezone.utc)
    def iso(dt):
        return dt.isoformat(timespec='seconds').replace('+00:00', 'Z')
    for family_index, (name, split, rows) in enumerate(FAMILIES):
        rows = list(rows)
        # Authoring order is not a review priority or an annotation hint.
        random.Random(20261014 + family_index).shuffle(rows)
        for case_index, row in enumerate(rows, 1):
            number = len(cases) + 1
            group = f'g-v2-{family_index + 1:02d}-{case_index:02d}'
            case_id = f'v2-{family_index + 1:02d}-{case_index:02d}'
            # Creation times describe asynchronous entry, independent of service dates.
            base = epoch + timedelta(days=rng.randrange(35), hours=rng.randrange(24), minutes=rng.randrange(60))
            service_dates = [datetime.fromisoformat(extra['expenseAt'].replace('Z', '+00:00'))
                             for extra in row['extra'] if 'expenseAt' in extra]
            if service_dates:
                base = max(base, max(service_dates) + timedelta(days=1))
            offsets = [0, rng.choice([0, 4, 37, 95, 840, 2880, 10080])]
            if rng.choice([True, False]):
                offsets.reverse()
            records = []
            for side_index, side in enumerate(('left', 'right')):
                document = row['docs'][side_index]
                digest = hashlib.sha256(f'fictional-v2/{group}/{document}'.encode()).hexdigest() if document is not None else None
                record = dict(
                    id=f'rv2-{number:03d}-{side[0]}',
                    incident=f'fictional-operation-{family_index + 1:02d}',
                    description=row[side],
                    amountCents=row['amounts'][side_index],
                    receiptDigest=digest,
                    transactionReference=row['refs'][side_index],
                    createdAt=iso(base + timedelta(minutes=offsets[side_index])),
                )
                record.update(row['extra'][side_index])
                records.append(record)
            cases.append(dict(id=case_id, groupId=group, supplyFamily=name,
                              category=row['category'], split=split, scenario=row['scenario'],
                              left=records[0], right=records[1]))
    random.Random(2026101401).shuffle(cases)
    return dict(
        schemaVersion=2,
        datasetId='waylatch-review-quality-v2',
        provenance={
            'kind':'new-fictional-synthetic-procurement',
            'authoredAt':'2026-10-14',
            'authoringInputs':['evaluation/review-quality-v2/PROTOCOL.md', 'scenario-author task instructions'],
            'authorAccess':'Scenario author did not read source implementation, v1 cases, predictions, annotations, or evaluation reports.',
            'method':'240 separately written pair narratives across 12 procurement families; a deterministic serializer supplies record IDs, synthetic document hashes and asynchronous entry timestamps.',
            'documents':'Receipt hashes represent fictional uploaded files, not reconstructed source documents. Shared files may contain multiple payable lines. Different hashes may represent copies, rescans, corrected forms, or different documents.',
            'scope':'Scenario narratives can include operational facts unavailable in predictor records. No supplier identity or receipt line allocation is added to the persisted record schema.',
            'annotationStatus':'Unannotated. No author decision key, evidence-tier key, prediction, or model score is included.',
            'limitations':['Fictional narratives and common author conventions are not operational prevalence evidence.', 'Transaction histories can remain unresolved; narratives intentionally do not guarantee binary certainty.', 'Creation timestamps are synthetic entry times and must not be read as service dates.'],
        },
        splitPolicy={
            'unit':'supply-family',
            'calibrationFamilies':[name for name, split, _ in FAMILIES if split == 'calibration'],
            'heldoutFamilies':[name for name, split, _ in FAMILIES if split == 'heldout'],
            'caseCounts':{'calibration':80,'heldout':160},
            'groupIsolation':'Each procurement dossier has a unique groupId; no family or group appears in both splits.',
            'annotationProtocol':'Separate blind reviewers receive shuffled id/scenario/left/right packets only; category, split and supplyFamily are withheld.',
        },
        cases=cases,
    )


def validate(dataset):
    cases = dataset['cases']
    assert len(cases) == 240
    assert len({case['id'] for case in cases}) == 240
    assert len({case['groupId'] for case in cases}) == 240
    record_ids = []
    excluded = {'potable-water','batteries-lighting','medical-dressings','generator-fuel','sanitation-hygiene','infant-feeding','radio-communications','shelter-structures','bulk-meals','flood-pumps','passenger-transport','power-distribution'}
    assert not excluded.intersection({case['supplyFamily'] for case in cases})
    allowed = {'id','incident','description','amountCents','receiptDigest','transactionReference','createdAt','location','expenseAt','amountKind'}
    for case in cases:
        assert set(case) == {'id','groupId','supplyFamily','category','split','scenario','left','right'}
        for side in ('left','right'):
            record = case[side]
            assert set(record) <= allowed
            assert 6 <= len(record['id']) <= 48
            record_ids.append(record['id'])
            assert 1 <= len(record['description']) <= 2000
            amount = record['amountCents']
            assert amount is None or (type(amount) is int and 1 <= amount <= 10000000)
            digest = record['receiptDigest']
            assert digest is None or (len(digest) == 64 and all(c in '0123456789abcdef' for c in digest))
            ref = record['transactionReference']
            assert ref is None or len(ref) <= 100
            for field in ('createdAt','expenseAt'):
                if field in record:
                    datetime.fromisoformat(record[field].replace('Z','+00:00'))
            assert record.get('amountKind','unknown') in {'exact','estimate','unknown'}
            assert (record['amountCents'] is None) == (record['amountKind'] == 'unknown')
    assert len(set(record_ids)) == 480
    for split, expected in [('calibration',80),('heldout',160)]:
        part = [case for case in cases if case['split'] == split]
        assert len(part) == expected
        family_names = {case['supplyFamily'] for case in part}
        for name in family_names:
            assert sum(case['supplyFamily'] == name for case in part) == 20
    for field in ('supplyFamily','groupId'):
        a = {case[field] for case in cases if case['split'] == 'calibration'}
        b = {case[field] for case in cases if case['split'] == 'heldout'}
        assert not a & b

if __name__ == '__main__':
    dataset = make_dataset()
    validate(dataset)
    target = Path(__file__).with_name('cases.json')
    target.write_text(json.dumps(dataset, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(f'Wrote {len(dataset["cases"])} unannotated fictional cases to {target.name}')
    print('Validated 480 bounded records, 12 families, 20 cases per family, and disjoint 80/160 splits.')
